Date.prototype.yyyymmdd = function () {
  var mm = this.getMonth() + 1; // getMonth() is zero-based
  var dd = this.getDate();

  return [this.getFullYear(),
    (mm > 9 ? '' : '0') + mm,
    (dd > 9 ? '' : '0') + dd
  ].join('-');
};



window.addEventListener('click', function (e) {
    e = e || window.event;
    var target = e.target || e.srcElement;
    var body = document.getElementsByTagName("BODY")[0];

    if (target.hasAttribute('data-toggle') && target.getAttribute('data-toggle') == 'modal') {
        if (target.hasAttribute('data-target')) {
            var m_ID = target.getAttribute('data-target');
            document.getElementById(m_ID).classList.add('open');
            body.classList.add('modal-open');
            e.preventDefault();
        }
    }

    // Close modal window with 'data-dismiss' attribute or when the backdrop is clicked
    if ((target.hasAttribute('data-dismiss') && target.getAttribute('data-dismiss') == 'modal') || target.classList.contains('modal')) {
        var modal = document.querySelector('[class="modal open"]');
        modal.classList.remove('open');
        body.classList.remove('modal-open');
        e.preventDefault();
    }
}, false);



function navHighlighter(navClass, sectionClass) {

    const sections = document.querySelectorAll(sectionClass);
    const navs = document.querySelectorAll(navClass);

    if (sections.length && navs.length) {

        window.addEventListener("scroll", function() {

            let scrollY = window.pageYOffset;

            sections.forEach(current => {
                const sectionHeight = current.offsetHeight;

                const sectionTop = (current.getBoundingClientRect().top + window.pageYOffset) - 260;
                sectionId = current.getAttribute("id");

                if (scrollY > sectionTop && scrollY <= sectionTop + sectionHeight) {
                    document.querySelector(navClass + " a[href*=" + sectionId + "]").classList.add("text-purple");
                } else {
                    document.querySelector(navClass + " a[href*=" + sectionId + "]").classList.remove("text-purple");
                }
            });
        });

    }

}

navHighlighter('.js-article-nav', '.js-article');
navHighlighter('.js-subcategory-nav', '.js-subcategory');

function initSliderNews() {

    let splideSelector = document.querySelector('.js-splide-news');

    if (!splideSelector) {
        return false;
    }

    const splide = new Splide('.js-splide-news', {
        type: 'fade',
        autoplay: true,
        heightRatio: 0.5,
        pagination: false,
        arrows: false,
        cover: false,
        rewind: true
    });

    splide.on('active', function(item) {
        let current = document.querySelector('.js-splide-call.active');
        if (current) {
            current.classList.remove('active')
        }
        let next = document.querySelector("[data-slide='" + item.index + "']");
        if (next) {
            next.classList.add('active');
        }

    });

    document.querySelectorAll('.js-splide-call').forEach(function(el) {
        el.addEventListener('click', function(e) {
            splide.go(parseInt(el.dataset.slide));
        })
    })

    splide.mount();

}

initSliderNews()

