// Copy function
function copyLinkFunction(e) {

    var copyText = document.querySelector(".js--copy-link");
    var value = copyText.getAttribute('data-text');
    var copyTextSuccess = copyText.getAttribute('data-success');

    var textArea = document.createElement("textarea");
    textArea.value = value;
    document.body.appendChild(textArea);
    textArea.select();
    document.execCommand('copy');
    document.body.removeChild(textArea);

    jQuery(e).next().text(copyTextSuccess).fadeIn();
    setTimeout(function() {
        jQuery(e).next().fadeOut().text('');
    }, 2000);

}

// Accordion Toggle
var acc = document.getElementsByClassName("js--accordion");
var i;

for (i = 0; i < acc.length; i++) {
    acc[i].addEventListener("click", function() {

        this.classList.toggle("active");
        var panel = this.nextElementSibling;
        if (panel.style.maxHeight) {
            panel.style.maxHeight = null;
        } else {
            panel.style.maxHeight = panel.scrollHeight + "px";
        }
    });
}

function toggle(el, classname) {
    el.classList.toggle(classname)
}

// Toggle Menu
document.querySelectorAll('.js-megamenu-toggle').forEach((el) => {
    el.addEventListener('click', (e) => {

        if (el.parentElement.classList.contains('open')) {
            e.target.parentElement.classList.remove('open');
        } else {
            document.querySelectorAll('.c-MegaMenu__parent.open').forEach((el) => {
                el.classList.remove('open');
            });
            e.target.parentElement.classList.add('open');
        }

    })
})

